import{_ as t,o as r,c as a,ag as o}from"./chunks/framework.2cFhd8Ux.js";const u=JSON.parse('{"title":"Reading List","description":"","frontmatter":{"source":"resources/reading-list.md"},"headers":[],"relativePath":"resources/reading-list.md","filePath":"resources/reading-list.md"}'),n={name:"resources/reading-list.md"};function s(i,e,d,l,h,g){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="reading-list" tabindex="-1">Reading List <a class="header-anchor" href="#reading-list" aria-label="Permalink to &quot;Reading List&quot;">​</a></h1><blockquote><p>The evidence behind the course, organized by week. Each week&#39;s README names the one required reading (with its 150–250-word reading response on Canvas, 🔴 AI off); this page suggests a <strong>core pick</strong> per week and the rest of the evidence for going further. Tags: <strong>[Grad seminar]</strong> suits a 20-minute CS [5xxx] paper presentation (<a href="./../graduate/paper-presentations.html">graduate track</a>) · <strong>[Replicable]</strong> can be replicated in about four weeks at $0 with open-weight models and public data (<a href="./../graduate/empirical-study.html">empirical study</a>) · <strong>[PR]</strong> peer-reviewed or accepted · <strong>[Pre]</strong> preprint · <strong>[Ind]</strong> industry research · <strong>[Docs]</strong>, <strong>[News]</strong>, <strong>[Pract]</strong> (practitioner) as in the <a href="./../research/notes/evidence-senior.html">research notes</a>.</p></blockquote><p>Numbers below come from the arXiv, ACM or venue page or the primary post, as recorded in the course&#39;s <a href="./../research/notes/evidence-senior.html">evidence notes</a> (checked November 2026). Preprints are preprints: say so when you cite one. When a link breaks, search for the title and <a href="https://github.com/Boyu-Zhang-UOI/engineering-software-with-ai/issues/new/choose" target="_blank" rel="noreferrer">tell us</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Reading a paper for a reading response:</strong> abstract, then the figures and tables, then the threats-to-validity section, then decide whether the middle is worth your time. Your response should say what the evidence shows, what it doesn&#39;t, and what it changes about how you&#39;d work, with one number from the paper.</p></div><p><strong>Jump to:</strong> <a href="#week-1--from-vibe-coding-to-agentic-engineering">1</a> · <a href="#week-2--inside-real-agents">2</a> · <a href="#week-3--context-engineering">3</a> · <a href="#week-4--securing-agents">4</a> · <a href="#week-5--spec-driven-development">5</a> · <a href="#week-6--tests-as-oracles">6</a> · <a href="#week-7--measuring-test-adequacy">7</a> · <a href="#week-8--legacy-code">8</a> · <a href="#week-9--review-at-scale">9</a> · <a href="#week-10--supply-chain-and-secure-code">10</a> · <a href="#week-11--building-llm-features">11</a> · <a href="#week-12--evals-and-benchmarks">12</a> · <a href="#week-13--parallel-and-background-agents">13</a> · <a href="#week-14--evidence-and-responsibility">14</a> · <a href="#week-15--ship-and-reflect">15</a> · <a href="#graduate-seminar-set">Graduate seminar set</a> · <a href="#replicable-studies">Replicable studies</a></p><hr><h2 id="week-1--from-vibe-coding-to-agentic-engineering" tabindex="-1">Week 1 — From Vibe Coding to Agentic Engineering <a class="header-anchor" href="#week-1--from-vibe-coding-to-agentic-engineering" aria-label="Permalink to &quot;Week 1 — From Vibe Coding to Agentic Engineering&quot;">​</a></h2><p><strong>Core pick:</strong> METR, <a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">&quot;Many SWE-bench-Passing PRs Would Not Be Merged into Main&quot;</a> (Mar 2026). Short, and the course&#39;s &quot;maintainers vs graders&quot; teaser.</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>METR (above)</td><td>Four maintainers of scikit-learn, Sphinx and pytest reviewed 296 test-passing agent PRs; their merge rate ran 24.2 points below the automated grader, and they merged only 68% of the human golden patches</td><td>[Ind]</td></tr><tr><td>METR, <a href="https://metr.org/blog/2025-08-12-research-update-towards-reconciling-slowdown-with-time-horizons" target="_blank" rel="noreferrer">&quot;Algorithmic vs. Holistic Evaluation&quot;</a> (Aug 2025)</td><td>None of 15 reviewed agent PRs was mergeable as-is, though 38% passed the tests; fixing them took 42 minutes on average</td><td>[Ind]</td></tr><tr><td>Kwa et al., <a href="https://arxiv.org/abs/2503.14499" target="_blank" rel="noreferrer">&quot;Measuring AI Ability to Complete Long Software Tasks&quot;</a>, NeurIPS 2025</td><td>Defines the 50% time horizon; it has doubled roughly every 7 months since 2019</td><td>[PR] <strong>[Grad seminar]</strong></td></tr><tr><td>Thorsten Ball, <a href="https://ampcode.com/how-to-build-an-agent" target="_blank" rel="noreferrer">&quot;How to build an agent&quot;</a></td><td>A working coding agent in under 400 lines with three tools: the shape of this week&#39;s lab</td><td>[Pract]</td></tr><tr><td><a href="https://github.com/SWE-agent/mini-swe-agent" target="_blank" rel="noreferrer">mini-swe-agent</a></td><td>About 100 lines of Python, bash only, and a strong SWE-bench Verified score: how little harness a capable model needs</td><td>[Pract]</td></tr></tbody></table><h2 id="week-2--inside-real-agents" tabindex="-1">Week 2 — Inside Real Agents <a class="header-anchor" href="#week-2--inside-real-agents" aria-label="Permalink to &quot;Week 2 — Inside Real Agents&quot;">​</a></h2><p><strong>Core pick:</strong> Anthropic Engineering, <a href="https://www.anthropic.com/engineering/claude-code-sandboxing" target="_blank" rel="noreferrer">&quot;Beyond permission prompts: making Claude Code more secure and autonomous&quot;</a> (Oct 2025). How a production harness thinks about permissions and sandboxes.</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Anthropic (above)</td><td>Filesystem <em>and</em> network isolation are both needed; sandboxing cut internal permission prompts by 84%</td><td>[Vendor]</td></tr><tr><td>Watanabe et al., <a href="https://arxiv.org/abs/2509.14745" target="_blank" rel="noreferrer">&quot;On the Use of Agentic Coding&quot;</a></td><td>Of 567 Claude Code PRs in 157 projects, 83.8% were merged, but 45.1% of those needed further changes</td><td>[Pre]</td></tr><tr><td>Li, Zhang &amp; Hassan, <a href="https://arxiv.org/abs/2507.15003" target="_blank" rel="noreferrer">&quot;The Rise of AI Teammates in SE 3.0&quot;</a> (the AIDev dataset; <a href="https://github.com/SAILResearch/AI_Teammates_in_SE3" target="_blank" rel="noreferrer">data</a>)</td><td>456,000+ PRs by five agents in 61,000 repositories; agent PRs are faster but accepted less often. The dataset behind most 2026 agent-PR studies</td><td>[Pre]</td></tr><tr><td>Murphy-Hill, Butler &amp; Savelieva, <a href="https://arxiv.org/abs/2607.01418" target="_blank" rel="noreferrer">&quot;Adoption and Impact of Command-Line AI Coding Agents&quot;</a></td><td>At Microsoft, adopters merged about 24% more PRs than their counterfactual for four months; adoption spread through social networks</td><td>[Pre/Ind]</td></tr><tr><td>Merrill et al., <a href="https://arxiv.org/abs/2601.11868" target="_blank" rel="noreferrer">&quot;Terminal-Bench&quot;</a>, ICLR 2026</td><td>89 terminal tasks with environments and verification tests; frontier agents score below 65%</td><td>[PR]</td></tr></tbody></table><h2 id="week-3--context-engineering" tabindex="-1">Week 3 — Context Engineering <a class="header-anchor" href="#week-3--context-engineering" aria-label="Permalink to &quot;Week 3 — Context Engineering&quot;">​</a></h2><p><strong>Core pick:</strong> Denisov-Blanch et al., <a href="https://arxiv.org/abs/2608.25241" target="_blank" rel="noreferrer">&quot;A Few Pages of Markdown&quot;</a> (Sep 2026).</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Denisov-Blanch et al. (above)</td><td>In 441 repositories, agents raised commits 28–38%; agent-first repositories without a committed AI config saw complexity rise 53% vs 27% with one; 73.8% of config files were never edited after the first commit. Observational</td><td>[Pre]</td></tr><tr><td>Hong, Troynikov &amp; Huber (Chroma), <a href="https://www.trychroma.com/research/context-rot" target="_blank" rel="noreferrer">&quot;Context Rot&quot;</a></td><td>All 18 models degraded with longer inputs; a focused ~300-token prompt beat the full 113K-token one</td><td>[Vendor research]</td></tr><tr><td>Anthropic, <a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">&quot;Effective context engineering for AI agents&quot;</a></td><td>Why long sessions degrade and how harnesses manage context (collected by the sibling course)</td><td>[Vendor]</td></tr><tr><td>Michigan EECS 498, <a href="https://github.com/eecs498-aase/materials/blob/HEAD/egm/README.md" target="_blank" rel="noreferrer">the Elephant-Goldfish Model</a></td><td>Where the <a href="./agent-patterns.html#the-goldfish-test">Goldfish test</a> comes from</td><td>[Pract]</td></tr></tbody></table><h2 id="week-4--securing-agents" tabindex="-1">Week 4 — Securing Agents <a class="header-anchor" href="#week-4--securing-agents" aria-label="Permalink to &quot;Week 4 — Securing Agents&quot;">​</a></h2><p><strong>Core pick:</strong> Simon Willison, <a href="https://simonwillison.net/2025/Jul/6/supabase-mcp-lethal-trifecta/" target="_blank" rel="noreferrer">&quot;Supabase MCP can leak your entire SQL database&quot;</a> (Jul 2025). The lethal trifecta in one page.</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Willison (above)</td><td>One MCP server supplies all three legs; a read-only server removes the way out (<a href="./case-studies.html#a1-supabase-mcp-the-lethal-trifecta-in-one-server">case A1</a>)</td><td>[Pract]</td></tr><tr><td>Liu et al., <a href="https://arxiv.org/abs/2509.22040" target="_blank" rel="noreferrer">&quot;&#39;Your AI, My Shell&#39;&quot;</a></td><td>314 payloads in project files and rules made Cursor and Copilot run malicious commands up to 84% of the time</td><td>[Pre] <strong>[Grad seminar]</strong></td></tr><tr><td>Debenedetti et al., <a href="https://arxiv.org/abs/2503.18813" target="_blank" rel="noreferrer">&quot;Defeating Prompt Injections by Design&quot; (CaMeL)</a></td><td>Privileged planner, quarantined parser, capability policies: 77% of AgentDojo tasks with provable security vs 84% undefended</td><td>[Pre/Ind] <strong>[Grad seminar]</strong></td></tr><tr><td>Beurer-Kellner et al., <a href="https://arxiv.org/abs/2506.08837" target="_blank" rel="noreferrer">&quot;Design Patterns for Securing LLM Agents against Prompt Injections&quot;</a></td><td>Six patterns with provable resistance, each with its utility cost</td><td>[Pre] <strong>[Grad seminar]</strong></td></tr><tr><td>Invariant Labs, <a href="https://invariantlabs.ai/blog/mcp-security-notification" target="_blank" rel="noreferrer">tool poisoning</a> and <a href="https://invariantlabs.ai/blog/mcp-github-vulnerability" target="_blank" rel="noreferrer">GitHub MCP exploited</a></td><td>Hidden instructions in tool descriptions; a public issue leaking a private repository</td><td>[Vendor research]</td></tr><tr><td><a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/security_best_practices" target="_blank" rel="noreferrer">MCP Security Best Practices</a></td><td>The specification&#39;s own attack catalogue</td><td>[Docs]</td></tr><tr><td>OWASP, <a href="https://genai.owasp.org/resource/owasp-genai-llm-top-10-2026/" target="_blank" rel="noreferrer">GenAI LLM Top 10 2026</a></td><td>Prompt Injection first, Excessive Agency up to third</td><td>[Docs]</td></tr></tbody></table><h2 id="week-5--spec-driven-development" tabindex="-1">Week 5 — Spec-Driven Development <a class="header-anchor" href="#week-5--spec-driven-development" aria-label="Permalink to &quot;Week 5 — Spec-Driven Development&quot;">​</a></h2><p><strong>Core pick:</strong> Martin Kleppmann, <a href="https://martin.kleppmann.com/2025/12/08/ai-formal-verification.html" target="_blank" rel="noreferrer">&quot;Prediction: AI will make formal verification go mainstream&quot;</a> (Dec 2025). The bottleneck moves to writing specifications.</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Kleppmann (above), with Bursuc et al., <a href="https://arxiv.org/abs/2509.22908" target="_blank" rel="noreferrer">&quot;A benchmark for vericoding&quot;</a></td><td>LLMs produced verified code for 82% of specifications in Dafny, 44% in Verus, 27% in Lean; pure Dafny rose from 68% to 96% in a year</td><td>[Pract] / [Pre]</td></tr><tr><td>Konstantinou, Tambon &amp; Papadakis, <a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">&quot;On the risk of coding before testing&quot;</a></td><td>Tests generated after faulty code caught 14% of faults vs 25% when generated independently (collected by the sibling course)</td><td>[Pre]</td></tr><tr><td>UT Austin CS 378, <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">course page</a></td><td>Homework &quot;in beats&quot;: &quot;the spec changes under you&quot;</td><td>[Docs]</td></tr></tbody></table><h2 id="week-6--tests-as-oracles" tabindex="-1">Week 6 — Tests as Oracles <a class="header-anchor" href="#week-6--tests-as-oracles" aria-label="Permalink to &quot;Week 6 — Tests as Oracles&quot;">​</a></h2><p><strong>Core pick:</strong> Maaz, DeVoe, Hatfield-Dodds &amp; Carlini, <a href="https://arxiv.org/abs/2510.09907" target="_blank" rel="noreferrer">&quot;Agentic Property-Based Testing&quot;</a> (NeurIPS 2025; <a href="https://github.com/mmaaz-git/agentic-pbt" target="_blank" rel="noreferrer">code</a>).</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Maaz et al. (above)</td><td>An agent driven by one Markdown prompt wrote Hypothesis tests for 100 packages; 56% of its reports were valid bugs (86% of the top 21); patches merged in NumPy and elsewhere</td><td>[PR] <strong>[Grad seminar]</strong></td></tr><tr><td>Konstantinou, Degiovanni &amp; Papadakis, <a href="https://arxiv.org/abs/2410.21136" target="_blank" rel="noreferrer">&quot;Can we find bugs using LLM-generated oracles?&quot;</a></td><td>LLM oracles capture actual rather than expected behavior, hiding bugs</td><td>[Pre]</td></tr><tr><td>Shi, Luo, Yang &amp; Tian, <a href="https://arxiv.org/abs/2610.32548" target="_blank" rel="noreferrer">&quot;Beyond Coverage and Mutation&quot;</a></td><td>In 14,320 LLM tests, null inputs were tested 34.8% of the time, negatives 23.8%, empties 38.8%, booleans over 93%</td><td>[Pre]</td></tr><tr><td>Alshahwan et al. (Meta), <a href="https://arxiv.org/abs/2402.09171" target="_blank" rel="noreferrer">&quot;Automated Unit Test Improvement using LLMs at Meta&quot;</a>, FSE 2024</td><td>A build → pass → coverage filter: 75% built, 57% passed reliably, 25% raised coverage</td><td>[PR/Ind]</td></tr><tr><td>Huang, Zhang, Harman et al., <a href="https://arxiv.org/abs/2508.00408" target="_blank" rel="noreferrer">&quot;Benchmarking LLMs for Unit Test Generation from Real-World Functions&quot;</a></td><td>On 3,909 real functions: 45.1% statement coverage, 40.2% mutation score, against about 92% coverage on an older benchmark</td><td>[Pre]</td></tr></tbody></table><h2 id="week-7--measuring-test-adequacy" tabindex="-1">Week 7 — Measuring Test Adequacy <a class="header-anchor" href="#week-7--measuring-test-adequacy" aria-label="Permalink to &quot;Week 7 — Measuring Test Adequacy&quot;">​</a></h2><p><strong>Core pick:</strong> Foster, Gulati, Harman et al. (Meta), <a href="https://arxiv.org/abs/2501.12862" target="_blank" rel="noreferrer">&quot;Mutation-Guided LLM-based Test Generation at Meta&quot;</a> (FSE 2025 Industry).</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Foster et al. (above)</td><td>Mutants representing a concern (privacy), then tests to kill them; the equivalent-mutant detector reached 0.95/0.96 precision/recall; engineers accepted 73% of tests</td><td>[PR/Ind] <strong>[Grad seminar]</strong></td></tr><tr><td>Zhao, Zhou &amp; Cohen, <a href="https://arxiv.org/abs/2607.22880" target="_blank" rel="noreferrer">&quot;Do Coverage and Mutation Scores of LLM-Generated Test Suites Correlate with Their Effectiveness?&quot;</a>, ISSTA 2026</td><td>The ISSTA caveat: both measures help in regression settings but are unreliable when the code may already be buggy</td><td>[PR] <strong>[Grad seminar] [Replicable]</strong></td></tr><tr><td>Wang, Chen, Deng et al., <a href="https://arxiv.org/abs/2406.09843" target="_blank" rel="noreferrer">&quot;A Comprehensive Study on LLMs for Mutation Testing&quot;</a></td><td>LLM mutants detected 87.98% of 851 real faults vs 41.64% for rule-based ones, at the cost of more non-compilable and equivalent mutants</td><td>[Pre]</td></tr><tr><td>MutGen, <a href="https://arxiv.org/html/2506.02954v5" target="_blank" rel="noreferrer">arXiv 2506.02954</a></td><td>Suites with 100% coverage can have a 4% mutation score</td><td>[Pre]</td></tr></tbody></table><h2 id="week-8--legacy-code" tabindex="-1">Week 8 — Legacy Code <a class="header-anchor" href="#week-8--legacy-code" aria-label="Permalink to &quot;Week 8 — Legacy Code&quot;">​</a></h2><p><strong>Core pick:</strong> He, Miller, Agarwal, Kästner &amp; Vasilescu, <a href="https://arxiv.org/abs/2511.04427" target="_blank" rel="noreferrer">&quot;Does AI-Assisted Coding Deliver?&quot;</a> (MSR 2026).</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>He et al. (above)</td><td>807 Cursor-adopting repositories vs 1,380 matched controls: lines added rose 281% in month 1 and the gain faded within about two months, while static-analysis warnings (+29.7%) and complexity (+40.7%; the text says 25.1%) stayed up</td><td>[PR] <strong>[Grad seminar]</strong></td></tr><tr><td>Borg et al., <a href="https://arxiv.org/abs/2507.00788" target="_blank" rel="noreferrer">&quot;Echoes of AI&quot;</a>, ICSME 2025 registered report</td><td>AI cut median completion time 30.7%, but other developers later evolving that code showed no significant difference in time or quality. A model preregistered design</td><td>[PR] <strong>[Grad seminar]</strong></td></tr><tr><td>CMU 17-313, <a href="https://cmu-313.github.io/assignments/P1/2_refactoring/" target="_blank" rel="noreferrer">P1B refactoring</a></td><td>An onboarding assignment that starts with a measurable refactor on a real agent codebase</td><td>[Docs]</td></tr></tbody></table><h2 id="week-9--review-at-scale" tabindex="-1">Week 9 — Review at Scale <a class="header-anchor" href="#week-9--review-at-scale" aria-label="Permalink to &quot;Week 9 — Review at Scale&quot;">​</a></h2><p><strong>Core pick:</strong> Chowdhury, Banik, Ferdous &amp; Shamim, <a href="https://arxiv.org/abs/2604.03196" target="_blank" rel="noreferrer">&quot;From Industry Claims to Empirical Reality&quot;</a> (MSR 2026).</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Chowdhury et al. (above)</td><td>PRs reviewed only by code-review agents merged 45.2% of the time vs 68.4% with humans; 12 of 13 agents had signal ratios below 60%</td><td>[PR] <strong>[Replicable]</strong></td></tr><tr><td>Cihan et al., <a href="https://arxiv.org/abs/2412.18531" target="_blank" rel="noreferrer">&quot;Automated Code Review In Practice&quot;</a>, ICSE 2025 SEIP</td><td>At Beko, 73.8% of AI comments were resolved, but average closure time rose from 5h52m to 8h20m</td><td>[PR] <strong>[Grad seminar]</strong></td></tr><tr><td>Tantithamthavorn et al., <a href="https://arxiv.org/abs/2601.01129v2" target="_blank" rel="noreferrer">&quot;RovoDev Code Reviewer&quot;</a>, ICSE 2026 SEIP</td><td>At Atlassian, 38.7% of AI comments led to changes vs 44.45% of human comments; PR cycle time fell 30.8%. Read with Cihan for the opposite result</td><td>[PR/Ind] <strong>[Grad seminar]</strong></td></tr><tr><td>Sun et al., <a href="https://arxiv.org/abs/2501.15134" target="_blank" rel="noreferrer">&quot;BitsAI-CR&quot;</a> and <a href="https://arxiv.org/abs/2508.18771" target="_blank" rel="noreferrer">&quot;Does AI Code Review Lead to Code Changes?&quot;</a></td><td>Generate-then-filter reached 75% precision; across 22,000+ comments, concise, snippet-bearing or manually triggered comments led to changes more often</td><td>[Pre]</td></tr><tr><td>GitHub, <a href="https://github.blog/ai-and-ml/github-copilot/60-million-copilot-code-reviews-and-counting/" target="_blank" rel="noreferrer">&quot;60 million Copilot code reviews and counting&quot;</a></td><td>29% of reviews deliberately say nothing; a stronger model gave +6% positive feedback for +16% latency</td><td>[Vendor]</td></tr><tr><td>Peralta et al., <a href="https://arxiv.org/abs/2605.22534" target="_blank" rel="noreferrer">&quot;Why Are Agentic Pull Requests Merged or Rejected?&quot;</a>, MSR 2026</td><td>Only 35.7% of rejections were clear agent failures; &quot;rejected&quot; is a noisy label for &quot;bad&quot;</td><td>[PR]</td></tr><tr><td>Li, Dutta &amp; Naik, <a href="https://arxiv.org/abs/2405.17238" target="_blank" rel="noreferrer">&quot;IRIS&quot;</a></td><td>An LLM inferring taint specifications for CodeQL found 55 of 120 CVEs vs 27 for CodeQL alone</td><td>[Pre]</td></tr><tr><td>Oliveira et al., <a href="https://arxiv.org/abs/2604.23251" target="_blank" rel="noreferrer">arXiv 2604.23251</a>, ICSE-SEET 2026</td><td>AI review in a 100+-student capstone: failed AI reviews fell from 227 to 0 after tool and instruction fixes. Pilot your bot</td><td>[PR]</td></tr></tbody></table><h2 id="week-10--supply-chain-and-secure-code" tabindex="-1">Week 10 — Supply Chain and Secure Code <a class="header-anchor" href="#week-10--supply-chain-and-secure-code" aria-label="Permalink to &quot;Week 10 — Supply Chain and Secure Code&quot;">​</a></h2><p><strong>Core pick:</strong> Vero et al., <a href="https://arxiv.org/abs/2502.11844" target="_blank" rel="noreferrer">&quot;BaxBench&quot;</a> (2025).</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Vero et al. (above)</td><td>392 backend tasks with functional tests and end-to-end exploits: the best model was 62% correct, and about half of correct programs were exploitable</td><td>[Pre] <strong>[Grad seminar]</strong></td></tr><tr><td>CISA, <a href="https://www.cisa.gov/news-events/alerts/2025/09/23/widespread-supply-chain-compromise-impacting-npm-ecosystem" target="_blank" rel="noreferrer">&quot;Widespread Supply Chain Compromise Impacting npm Ecosystem&quot;</a></td><td>Shai-Hulud compromised 500+ packages; audit lockfiles, pin, rotate, phishing-resistant MFA</td><td>[Gov]</td></tr><tr><td>Siddiq et al., <a href="https://arxiv.org/abs/2601.00477" target="_blank" rel="noreferrer">&quot;Security in the Age of AI Teammates&quot;</a></td><td>About 4% of 33,000+ agentic PRs are security-related; they merge less often and wait longer</td><td>[Pre]</td></tr><tr><td>Package hallucination: <a href="https://labs.cloudsecurityalliance.org/research/csa-research-note-slopsquatting-ai-supply-chain-20260419-csa/" target="_blank" rel="noreferrer">CSA note on the USENIX Security 2025 study</a> and the <a href="https://arxiv.org/abs/2605.17062" target="_blank" rel="noreferrer">2026 re-test</a></td><td>21.7% / 5.2% invented names in 2025; 4.6–6.1% in 2026 frontier models (<a href="./case-studies.html#b5-slopsquatting-packages-that-dont-exist">case B5</a>)</td><td>[Pre]</td></tr></tbody></table><h2 id="week-11--building-llm-features" tabindex="-1">Week 11 — Building LLM Features <a class="header-anchor" href="#week-11--building-llm-features" aria-label="Permalink to &quot;Week 11 — Building LLM Features&quot;">​</a></h2><p><strong>Core pick:</strong> Tam et al., <a href="https://aclanthology.org/2024.emnlp-industry.91/" target="_blank" rel="noreferrer">&quot;Let Me Speak Freely?&quot;</a> (EMNLP 2024 Industry), read with .txt&#39;s reply, <a href="https://blog.dottxt.ai/say-what-you-mean.html" target="_blank" rel="noreferrer">&quot;Say What You Mean&quot;</a>.</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Tam et al. vs .txt (above), with OpenAI, <a href="https://openai.com/index/introducing-structured-outputs-in-the-api/" target="_blank" rel="noreferrer">&quot;Introducing Structured Outputs&quot;</a></td><td>Tam et al. report reasoning declines under format restrictions; .txt traces it to mismatched prompts and an LLM answer parser, and with matched prompts finds structured output equal or better (GSM8K 0.77→0.78). OpenAI reports 100% schema adherence</td><td>[PR] / [Vendor] <strong>[Replicable]</strong></td></tr><tr><td>Yao et al., <a href="https://arxiv.org/abs/2406.12045" target="_blank" rel="noreferrer">&quot;τ-bench&quot;</a></td><td>Tool-calling agents succeeded on under 50% of tasks; pass^8 below 25% in retail. Introduces pass^k</td><td>[Pre]</td></tr><tr><td>Barnett et al., <a href="https://arxiv.org/abs/2401.05856" target="_blank" rel="noreferrer">&quot;Seven Failure Points When Engineering a RAG System&quot;</a>, CAIN 2024; with Es et al., <a href="https://arxiv.org/abs/2309.15217" target="_blank" rel="noreferrer">&quot;Ragas&quot;</a></td><td>RAG &quot;can only be fully validated in operation&quot;; Ragas&#39; metrics are themselves LLM judges</td><td>[PR] / [Pre]</td></tr><tr><td>Chroma, <a href="https://www.trychroma.com/research/context-rot" target="_blank" rel="noreferrer">&quot;Context Rot&quot;</a></td><td>The cost and latency case for small contexts</td><td>[Vendor research]</td></tr></tbody></table><h2 id="week-12--evals-and-benchmarks" tabindex="-1">Week 12 — Evals and Benchmarks <a class="header-anchor" href="#week-12--evals-and-benchmarks" aria-label="Permalink to &quot;Week 12 — Evals and Benchmarks&quot;">​</a></h2><p><strong>Core pick:</strong> Hamel Husain, <a href="https://hamel.dev/blog/posts/llm-judge/" target="_blank" rel="noreferrer">&quot;Using LLM-as-a-Judge For Evaluation: A Complete Guide&quot;</a> (revised 2026).</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Husain (above)</td><td>Binary pass/fail labels with critiques from one expert; about 100 labels per failure mode; report true-positive and true-negative rates</td><td>[Pract]</td></tr><tr><td>Shankar et al., <a href="https://arxiv.org/abs/2404.12272" target="_blank" rel="noreferrer">&quot;Who Validates the Validators?&quot;</a>, UIST 2024</td><td>Criteria drift: grading outputs changes the criteria</td><td>[PR] <strong>[Grad seminar]</strong></td></tr><tr><td>Thakur et al., <a href="https://arxiv.org/abs/2406.12624" target="_blank" rel="noreferrer">&quot;Judging the Judges&quot;</a>, GEM² at ACL 2025</td><td>Among 13 judges only the largest approached humans; high percent agreement hid large score gaps, so report κ</td><td>[PR] <strong>[Replicable]</strong></td></tr><tr><td>Wang, Guo, Gao et al., <a href="https://arxiv.org/abs/2502.06193" target="_blank" rel="noreferrer">&quot;Can LLMs Replace Human Evaluators?&quot;</a>, ISSTA 2025</td><td>For code, the best judges correlated with humans at r ≈ 0.81 (translation) and 0.69 (generation)</td><td>[PR]</td></tr><tr><td>Anthropic, <a href="https://www.anthropic.com/engineering/demystifying-evals-for-ai-agents" target="_blank" rel="noreferrer">&quot;Demystifying evals for AI agents&quot;</a>; Miller, <a href="https://arxiv.org/abs/2411.00640" target="_blank" rel="noreferrer">&quot;Adding Error Bars to Evals&quot;</a></td><td>Capability vs regression evals; grade outcomes, not step sequences; standard errors, paired comparisons and power</td><td>[Vendor] / [Pre]</td></tr><tr><td>OpenAI, <a href="https://openai.com/index/why-we-no-longer-evaluate-swe-bench-verified/" target="_blank" rel="noreferrer">&quot;Why SWE-bench Verified no longer measures frontier coding capabilities&quot;</a></td><td>The co-creator stopped reporting it, citing contamination and flawed tests</td><td>[Ind]</td></tr><tr><td>Deng et al., <a href="https://arxiv.org/abs/2509.16941" target="_blank" rel="noreferrer">&quot;SWE-Bench Pro&quot;</a>; Gabor, <a href="https://jonathanpgabor.substack.com/p/swe-bench-pro-is-even-worse" target="_blank" rel="noreferrer">&quot;SWE-Bench Pro is even worse&quot;</a></td><td>1,865 contamination-resistant tasks; a hand audit of 100 found lenient and leaking tasks</td><td>[Pre] / [Pract]</td></tr><tr><td>Aleithan et al., <a href="https://arxiv.org/abs/2410.06992" target="_blank" rel="noreferrer">&quot;SWE-Bench+&quot;</a></td><td>Solution leakage and weak tests cut a resolve rate from 12.47% to 3.97%</td><td>[Pre]</td></tr><tr><td>Wang, Pradel &amp; Liu, <a href="https://arxiv.org/abs/2503.15223" target="_blank" rel="noreferrer">&quot;Are &#39;Solved Issues&#39; in SWE-bench Really Solved Correctly?&quot;</a></td><td>29.6% of plausible patches behave differently from the ground truth; 6.2 points of inflation</td><td>[Pre] <strong>[Grad seminar]</strong></td></tr><tr><td>Liang et al., <a href="https://arxiv.org/abs/2506.12286" target="_blank" rel="noreferrer">&quot;The SWE-Bench Illusion&quot;</a></td><td>Models name the buggy file from the issue alone 76% of the time on SWE-bench vs 53% elsewhere</td><td>[Pre] <strong>[Grad seminar] [Replicable]</strong></td></tr><tr><td>Zhu et al., <a href="https://arxiv.org/abs/2507.02825" target="_blank" rel="noreferrer">&quot;Establishing Best Practices for Building Rigorous Agentic Benchmarks&quot;</a></td><td>The Agentic Benchmark Checklist: flaws distort scores by up to 100% relative</td><td>[Pre] <strong>[Grad seminar]</strong></td></tr><tr><td>SWE-bench-Live (<a href="https://arxiv.org/abs/2505.23419" target="_blank" rel="noreferrer">arXiv 2505.23419</a>), SWE-rebench (<a href="https://huggingface.co/papers/2505.20411" target="_blank" rel="noreferrer">2505.20411</a>), LiveCodeBench (<a href="https://arxiv.org/abs/2403.07974" target="_blank" rel="noreferrer">2403.07974</a>), SWE-bench Multimodal (<a href="https://arxiv.org/abs/2410.03859" target="_blank" rel="noreferrer">2410.03859</a>)</td><td>Refreshed and date-windowed benchmarks</td><td>[Pre]</td></tr></tbody></table><h2 id="week-13--parallel-and-background-agents" tabindex="-1">Week 13 — Parallel and Background Agents <a class="header-anchor" href="#week-13--parallel-and-background-agents" aria-label="Permalink to &quot;Week 13 — Parallel and Background Agents&quot;">​</a></h2><p><strong>Core pick:</strong> Peralta et al., <a href="https://arxiv.org/abs/2605.22534" target="_blank" rel="noreferrer">&quot;Why Are Agentic Pull Requests Merged or Rejected? An Empirical Study&quot;</a> (MSR 2026), read for what a merge rate does and doesn&#39;t measure before your team computes its own.</p><p>The evidence on parallel agents is thin: courses teach worktrees and orchestration, but none has published outcome data (<a href="./../research/notes/courses-upper-division.html">research notes</a>). That makes week 13&#39;s own measurement of review time worth doing carefully.</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Peralta et al. (above)</td><td>In 717 cases inspected by hand (from 9,799 reviewed agent PRs), only 35.7% of rejections were clear agent failures; 31.2% came from workflow constraints, and 33.1% had no visible rationale</td><td>[PR]</td></tr><tr><td>Murphy-Hill, Butler &amp; Savelieva, <a href="https://arxiv.org/abs/2607.01418" target="_blank" rel="noreferrer">&quot;Adoption and Impact of Command-Line AI Coding Agents&quot;</a> (on week 2&#39;s list)</td><td>At Microsoft, adopters merged about 24% more PRs than their counterfactual for four months; adoption spread through social networks</td><td>[Pre/Ind]</td></tr><tr><td>Robbes et al., <a href="https://arxiv.org/abs/2601.18341" target="_blank" rel="noreferrer">&quot;Agentic Much?&quot;</a></td><td>22.2–28.7% of 128,018 GitHub projects had adopted agents</td><td>[Pre]</td></tr><tr><td>UT Austin CS 378, <a href="https://www.cs.utexas.edu/~witchel/378AC/schedule.html" target="_blank" rel="noreferrer">schedule</a></td><td>&quot;Parallelize a task once you can name its merge point&quot;</td><td>[Docs]</td></tr></tbody></table><h2 id="week-14--evidence-and-responsibility" tabindex="-1">Week 14 — Evidence and Responsibility <a class="header-anchor" href="#week-14--evidence-and-responsibility" aria-label="Permalink to &quot;Week 14 — Evidence and Responsibility&quot;">​</a></h2><p><strong>Core pick:</strong> one productivity study, its follow-up, and one maintainer policy: Becker et al., <a href="https://arxiv.org/abs/2507.09089" target="_blank" rel="noreferrer">the METR randomized trial with experienced open-source developers</a>; METR&#39;s <a href="https://metr.org/blog/2026-02-24-uplift-update/" target="_blank" rel="noreferrer">&quot;uplift update&quot;</a> (Feb 2026), on why the follow-up&#39;s own estimates are unreliable; and <a href="https://github.com/llvm/llvm-project/blob/main/llvm/docs/AIToolPolicy.md" target="_blank" rel="noreferrer">LLVM&#39;s AI Tool Policy</a>.</p><table tabindex="0"><thead><tr><th>Read</th><th>What it shows</th><th>Tags</th></tr></thead><tbody><tr><td>Becker et al. (above)</td><td>The METR randomized trial (collected by the sibling course); an alternate seminar paper</td><td>[Pre] (alternate)</td></tr><tr><td>Cui, Demirer, Jaffe, Musolff, Peng &amp; Salz, <a href="https://pubsonline.informs.org/doi/fpi/10.1287/mnsc.2025.00535" target="_blank" rel="noreferrer">&quot;The Effects of Generative AI on High-Skilled Work&quot;</a>, <em>Management Science</em> 2026</td><td>Randomized rollouts for 4,867 developers: +26.08% completed tasks (SE 10.3%); juniors +27–39%, seniors +8–13%; quality not observed</td><td>[PR] <strong>[Grad seminar]</strong></td></tr><tr><td>Paradis et al. (Google), <a href="https://arxiv.org/abs/2410.12944" target="_blank" rel="noreferrer">&quot;How much does AI impact development speed?&quot;</a></td><td>96 engineers; best estimate about 21% less time, wide CI</td><td>[Pre/Ind]</td></tr><tr><td>Lee et al. (Microsoft Research), <a href="https://advait.org/files/lee_2025_ai_critical_thinking_survey.pdf" target="_blank" rel="noreferrer">&quot;The Impact of Generative AI on Critical Thinking&quot;</a>, CHI 2025</td><td>319 knowledge workers: confidence in the AI predicted less critical thinking; self-confidence predicted more</td><td>[PR] <strong>[Grad seminar]</strong></td></tr><tr><td>Balepur et al., <a href="https://arxiv.org/abs/2607.26375" target="_blank" rel="noreferrer">&quot;(Im)Paired Programming&quot;</a></td><td>54 students finished faster with an agent but understood less, and still preferred agents</td><td>[Pre]</td></tr><tr><td>Shen &amp; Tamkin, <a href="https://arxiv.org/abs/2601.20245" target="_blank" rel="noreferrer">skill-formation RCT</a></td><td>Lower quiz scores when learning with AI (collected by the sibling course); an alternate seminar paper</td><td>[Pre] (alternate)</td></tr><tr><td>Brynjolfsson, Chandar &amp; Chen, <a href="https://digitaleconomy.stanford.edu/news/canaries-interest-rates-and-timinga-more-on-recent-drivers-of-employment-changes-for-young-workers" target="_blank" rel="noreferrer">&quot;Canaries in the Coal Mine?&quot; follow-up</a></td><td>Employment of developers aged 22–25 down nearly 20% from the late-2022 peak; significant only after 2024 under stricter controls</td><td>[Pre]</td></tr><tr><td>Yu &amp; Moon, <a href="https://arxiv.org/abs/2607.17067" target="_blank" rel="noreferrer">&quot;Who Will Become the Next Senior?&quot;</a>, AIES 2026; Baltes, Cheong &amp; Treude, <a href="https://arxiv.org/abs/2603.27249" target="_blank" rel="noreferrer">&quot;An Endless Stream of AI Slop&quot;</a></td><td>&quot;Absorption&quot; of entry-level work; review friction and collective deskilling</td><td>[PR] / [Pre]</td></tr><tr><td>QEMU, <a href="https://www.qemu.org/docs/master/devel/code-provenance.html" target="_blank" rel="noreferrer">code provenance</a>; Ghostty, <a href="https://github.com/ghostty-org/ghostty/blob/main/AI_POLICY.md" target="_blank" rel="noreferrer">AI_POLICY.md</a>; Linux, <a href="https://github.com/torvalds/linux/blob/master/Documentation/process/coding-assistants.rst" target="_blank" rel="noreferrer">coding-assistants.rst</a>; Django, <a href="https://docs.djangoproject.com/en/dev/internals/contributing/writing-code/submitting-patches/" target="_blank" rel="noreferrer">AI-assisted contributions</a></td><td>The range of maintainer policies (<a href="./case-studies.html#maintainers-ai-policies">section E</a>)</td><td>[Docs]</td></tr><tr><td>Hora &amp; Robbes, <a href="https://arxiv.org/abs/2605.16706" target="_blank" rel="noreferrer">118 contributor AI policies</a></td><td>78% allow AI-assisted contributions, 51% require disclosure, 74% a human in the loop</td><td>[Pre]</td></tr><tr><td>Xu, Gao, He &amp; Zhou, <a href="https://arxiv.org/abs/2408.02487" target="_blank" rel="noreferrer">&quot;LiCoEval&quot;</a>, ICSE 2025</td><td>Even the best of 14 LLMs produced 0.88–2.01% of outputs &quot;strikingly similar&quot; to existing OSS code, and gave inaccurate licence information, especially for copyleft</td><td>[PR] <strong>[Grad seminar]</strong></td></tr><tr><td>Horikawa et al., <a href="https://arxiv.org/abs/2610.36229" target="_blank" rel="noreferrer">&quot;Agent or Human?&quot;</a></td><td>Detecting agent commits reaches precision 0.332 at realistic prevalence: detection &quot;cannot replace recorded attribution&quot;</td><td>[Pre]</td></tr><tr><td><em>Thaler v. Perlmutter</em>, cert. denied (<a href="https://www.scotusblog.com/cases/case-files/thaler-v-perlmutter" target="_blank" rel="noreferrer">SCOTUSblog</a>); <em>Bartz v. Anthropic</em> settlement (<a href="https://www.jurist.org/news/2026/07/judge-approves-record-1-5-billion-settlement-involving-anthropic/" target="_blank" rel="noreferrer">JURIST</a>)</td><td>The human-authorship requirement stands; training on lawfully bought books was fair use, keeping 7M+ pirated ones was not ($1.5B settlement)</td><td>[Legal]</td></tr></tbody></table><h2 id="week-15--ship-and-reflect" tabindex="-1">Week 15 — Ship and Reflect <a class="header-anchor" href="#week-15--ship-and-reflect" aria-label="Permalink to &quot;Week 15 — Ship and Reflect&quot;">​</a></h2><p><strong>Core pick:</strong> Kwa et al., <a href="https://arxiv.org/abs/2503.14499" target="_blank" rel="noreferrer">&quot;Measuring AI Ability to Complete Long Software Tasks&quot;</a> (NeurIPS 2025; on week 1&#39;s list), read for where the field is going; the reading response asks what the trend does and doesn&#39;t let you predict. If you read it in week 1 or presented it, read Kleppmann on formal verification (week 5) instead. Also worth a look: the <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">UT Austin</a> and <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">Michigan</a> course pages, to compare what other courses chose to teach.</p><hr><h2 id="graduate-seminar-set" tabindex="-1">Graduate seminar set <a class="header-anchor" href="#graduate-seminar-set" aria-label="Permalink to &quot;Graduate seminar set&quot;">​</a></h2><p>The nineteen <strong>[Grad seminar]</strong> papers, by the week whose topic they fit. Weeks 3, 5, 11 and 13 have none; the instructor moves papers to balance the schedule (<a href="./../graduate/paper-presentations.html">Paper Presentations</a>).</p><table tabindex="0"><thead><tr><th>Week</th><th>Papers</th></tr></thead><tbody><tr><td>3 (first slot)</td><td>Kwa et al. (time horizons)</td></tr><tr><td>4</td><td>Liu et al. (Your AI, My Shell) · Debenedetti et al. (CaMeL) · Beurer-Kellner et al. (design patterns)</td></tr><tr><td>6</td><td>Maaz et al. (agentic property-based testing)</td></tr><tr><td>7</td><td>Foster et al. (mutation-guided generation at Meta) · Zhao, Zhou &amp; Cohen (ISSTA 2026)</td></tr><tr><td>8</td><td>He et al. (Cursor difference-in-differences) · Borg et al. (Echoes of AI)</td></tr><tr><td>9</td><td>Cihan et al. (Beko) · Tantithamthavorn et al. (Atlassian)</td></tr><tr><td>10</td><td>Vero et al. (BaxBench)</td></tr><tr><td>12</td><td>Shankar et al. (criteria drift) · Wang, Pradel &amp; Liu (PatchDiff) · Liang et al. (SWE-Bench Illusion) · Zhu et al. (ABC)</td></tr><tr><td>14</td><td>Cui et al. (field experiments) · Lee et al. (critical thinking) · Xu et al. (LiCoEval)</td></tr><tr><td>Alternates</td><td>Becker et al. (METR RCT) · Shen &amp; Tamkin (skill formation)</td></tr></tbody></table><h2 id="replicable-studies" tabindex="-1">Replicable studies <a class="header-anchor" href="#replicable-studies" aria-label="Permalink to &quot;Replicable studies&quot;">​</a></h2><p>The five <strong>[Replicable]</strong> items, with the replication the evidence notes sketch. Each fits about four weeks at $0 using open-weight models on the lab machine and public data, with no human subjects (<a href="./../templates/STUDY_PROTOCOL.html">STUDY_PROTOCOL.md template</a>).</p><table tabindex="0"><thead><tr><th>Study</th><th>A $0 replication</th></tr></thead><tbody><tr><td>Liang et al., memorization probe</td><td>Run the file-path probe with 2–3 open-weight models on 200 SWE-bench Verified issues and 200 post-cutoff SWE-rebench or SWE-bench-Live issues; compare with bootstrap confidence intervals</td></tr><tr><td>Zhao, Zhou &amp; Cohen, coverage and mutation vs real bugs</td><td>Generate pytest suites with one local model for 10 BugsInPy projects (buggy and fixed versions); measure coverage.py and mutmut scores; correlate both with real-bug detection</td></tr><tr><td>Chowdhury et al., code-review agents vs humans</td><td>Repeat the merge-rate and signal analysis on a newer AIDev or GH Archive slice; hand-code 100 comments with two raters (yourselves) and report κ</td></tr><tr><td>Tam et al. vs .txt, structured output</td><td>With two local 7–8B models and grammar-constrained decoding, cross prompt (matched/mismatched) × decoding (free/constrained) × parser (regex/LLM) on GSM8K and Last Letter</td></tr><tr><td>Thakur et al., small-judge alignment</td><td>Rerun the comparison on the paper&#39;s released labels with 3–4 small open-weight judges; add one bias test (answer order or verbosity); report κ alongside percent agreement</td></tr></tbody></table>',58)])])}const p=t(n,[["render",s]]);export{u as __pageData,p as default};
